import { test, expect } from '@playwright/test';

test.describe('Bulk Delete Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/items');
  });

  test('should successfully bulk-delete selected items from a list', async ({ page }) => {
    // Verify initial list is displayed
    const listItems = page.getByRole('listitem');
    await expect(listItems).toHaveCount(5);

    // Select 3 items using checkboxes
    const checkbox1 = page.getByLabel('Item 1');
    await checkbox1.click();

    const checkbox2 = page.getByLabel('Item 2');
    await checkbox2.click();

    const checkbox3 = page.getByLabel('Item 3');
    await checkbox3.click();

    // Verify selection is visible
    const selectedCount = page.getByText('Selected: 3');
    await expect(selectedCount).toBeVisible();

    // Click bulk delete button
    const bulkDeleteButton = page.getByRole('button', { name: /bulk delete/i });
    await bulkDeleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm bulk delete/i });
    await expect(confirmModal).toBeVisible();

    // Verify confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button
    await confirmButton.click();

    // Verify success message
    const successMessage = page.getByText(/deleted 3 items/i);
    await expect(successMessage).toBeVisible();

    // Verify list is updated
    await expect(listItems).toHaveCount(2);

    // Verify items are removed from the list
    const item1 = page.getByText('Item 1');
    await expect(item1).not.toBeVisible();

    const item2 = page.getByText('Item 2');
    await expect(item2).not.toBeVisible();

    const item3 = page.getByText('Item 3');
    await expect(item3).not.toBeVisible();

    // Verify remaining items are still visible
    const remainingItem = page.getByText('Item 4');
    await expect(remainingItem).toBeVisible();

    const remainingItem2 = page.getByText('Item 5');
    await expect(remainingItem2).toBeVisible();
  });

  test('should handle bulk delete with no selected items', async ({ page }) => {
    // Verify initial list is displayed
    const listItems = page.getByRole('listitem');
    await expect(listItems).toHaveCount(5);

    // Click bulk delete button
    const bulkDeleteButton = page.getByRole('button', { name: /bulk delete/i });
    await bulkDeleteButton.click();

    // Verify confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm bulk delete/i });
    await expect(confirmModal).toBeVisible();

    // Verify confirm button is visible
    const confirmButton = page.getByRole('button', { name: /confirm/i });
    await expect(confirmButton).toBeVisible();

    // Click confirm button
    await confirmButton.click();

    // Verify success message
    const successMessage = page.getByText(/no items selected/i);
    await expect(successMessage).toBeVisible();

    // Verify list remains unchanged
    await expect(listItems).toHaveCount(5);
  });
});
